import{_ as t,o,c as a,a2 as r}from"./chunks/framework.D9E58p8B.js";const g=JSON.parse('{"title":"Overlay","description":"","frontmatter":{"title":"Overlay"},"headers":[],"relativePath":"en/reference/overlay.md","filePath":"en/reference/overlay.md"}'),s={name:"en/reference/overlay.md"};function i(n,e,d,l,h,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="overlay-showing-what-the-ai-is-doing" tabindex="-1">Overlay: showing what the AI is doing <a class="header-anchor" href="#overlay-showing-what-the-ai-is-doing" aria-label="Permalink to &quot;Overlay: showing what the AI is doing&quot;">​</a></h1><p>The Overlay is the visual layer that Daimon draws on top of the screen so that the person in front of the machine can see where the AI is looking and acting: frame, spotlight, cursor, banner. It is purely presentational.</p><p>All five tools have the same properties:</p><ul><li>they have no authorization level and are not subject to the ceiling;</li><li>they never block and never fail;</li><li>they always return <code>{&quot;ok&quot;: true}</code>, <strong>even if no overlay window is running</strong>: the order is then simply dropped. An <code>ok</code> therefore does not prove that the mark is visible;</li><li>the &quot;Présence à l&#39;écran&quot; (Presence on screen) setting in the panel enables the overlay.</li><li>by default (<code>anti_feedback</code> is <code>true</code> in the configuration), Overlay marks are <strong>invisible to any screen capture</strong>, including <a href="./vue.html#vue-snapshot"><code>vue_snapshot</code></a>: the AI never sees its own marks. You see them on the screen, but they do not appear in a capture; this is why this documentation shows none. On macOS, the overlay is a non-interactive window covering the main display.</li></ul><div class="warning custom-block"><p class="custom-block-title">Coordinate unit</p><p>Here, coordinates are <strong>raw global pixels</strong>, already resolved by you. There is no <code>space</code>, no <code>display</code>, no <code>region</code> (unlike Mains, which speaks in points). Do not pass image pixels: convert them first with <a href="./vue.html#vue-resolve"><code>vue_resolve</code></a>.</p></div><h2 id="helper" tabindex="-1">The Overlay helper <a class="header-anchor" href="#helper" aria-label="Permalink to &quot;The Overlay helper {#helper}&quot;">​</a></h2><p>The marks are drawn by a separate process, the <strong>helper</strong> (<code>Daimon overlay</code>). It exits on its own: 60 seconds after launch if it has had no client, and 3 seconds after its last client leaves.</p><p>The client <strong>relaunches the helper</strong> when a send fails for lack of a helper, provided that &quot;Présence à l&#39;écran&quot; is enabled, and at most once every 5 seconds. Enabling &quot;Présence à l&#39;écran&quot; in the panel also launches the helper; disabling it neither stops it nor relaunches it.</p><p>To know whether the helper is alive, call <a href="./diagnostic.html#daimon-doctor"><code>daimon_doctor</code></a> and read the <code>overlay</code> key. The <code>overlay.log</code> log, in Daimon&#39;s data folder, records <code>overlay: bound</code>, then <code>overlay: start enabled=&lt;true|false&gt;</code> at startup, and <code>overlay: exit reason=&lt;idle|startup&gt;</code> on exit, each line preceded by a UTC timestamp.</p><table tabindex="0"><thead><tr><th>Tool</th><th>Role</th><th>Level</th></tr></thead><tbody><tr><td><a href="#overlay-highlight"><code>overlay_highlight</code></a></td><td>Rounded frame around a region, with a label</td><td>none</td></tr><tr><td><a href="#overlay-spotlight"><code>overlay_spotlight</code></a></td><td>Darkens the screen except for a region</td><td>none</td></tr><tr><td><a href="#overlay-cursor"><code>overlay_cursor</code></a></td><td>Synthetic cursor halo</td><td>none</td></tr><tr><td><a href="#overlay-banner"><code>overlay_banner</code></a></td><td>Banner colored according to a level</td><td>none</td></tr><tr><td><a href="#overlay-clear"><code>overlay_clear</code></a></td><td>Clears all marks</td><td>none</td></tr></tbody></table><h2 id="overlay-highlight" tabindex="-1">overlay_highlight <a class="header-anchor" href="#overlay-highlight" aria-label="Permalink to &quot;overlay_highlight {#overlay-highlight}&quot;">​</a></h2><p>Draws a styled rounded rectangle, with an optional label, around a region.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Required</th><th>Role</th></tr></thead><tbody><tr><td><code>x</code></td><td>integer</td><td>none</td><td><strong>yes</strong></td><td>Left edge</td></tr><tr><td><code>y</code></td><td>integer</td><td>none</td><td><strong>yes</strong></td><td>Top edge</td></tr><tr><td><code>width</code></td><td>integer</td><td>none</td><td><strong>yes</strong></td><td>Width</td></tr><tr><td><code>height</code></td><td>integer</td><td>none</td><td><strong>yes</strong></td><td>Height</td></tr><tr><td><code>label</code></td><td>string</td><td><code>&quot;&quot;</code></td><td>no</td><td>Label displayed with the frame</td></tr></tbody></table><p><strong>Example call</strong></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;x&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">400</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;y&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">300</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;width&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">220</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;height&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;label&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Bouton Envoyer&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p><strong>Returns</strong>: <code>{&quot;ok&quot;: true}</code>.</p><h2 id="overlay-spotlight" tabindex="-1">overlay_spotlight <a class="header-anchor" href="#overlay-spotlight" aria-label="Permalink to &quot;overlay_spotlight {#overlay-spotlight}&quot;">​</a></h2><p>Darkens the screen except for a cleared hole over the region.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Required</th><th>Role</th></tr></thead><tbody><tr><td><code>x</code>, <code>y</code></td><td>integer</td><td>none</td><td><strong>yes</strong></td><td>Top-left corner of the region</td></tr><tr><td><code>width</code>, <code>height</code></td><td>integer</td><td>none</td><td><strong>yes</strong></td><td>Dimensions of the region</td></tr></tbody></table><p><strong>Example call</strong>: <code>{ &quot;x&quot;: 400, &quot;y&quot;: 300, &quot;width&quot;: 220, &quot;height&quot;: 60 }</code></p><p><strong>Returns</strong>: <code>{&quot;ok&quot;: true}</code>.</p><h2 id="overlay-cursor" tabindex="-1">overlay_cursor <a class="header-anchor" href="#overlay-cursor" aria-label="Permalink to &quot;overlay_cursor {#overlay-cursor}&quot;">​</a></h2><p>Places the synthetic cursor halo on a global point.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Required</th><th>Role</th></tr></thead><tbody><tr><td><code>x</code>, <code>y</code></td><td>integer</td><td>none</td><td><strong>yes</strong></td><td>Point</td></tr></tbody></table><p><strong>Example call</strong>: <code>{ &quot;x&quot;: 510, &quot;y&quot;: 330 }</code></p><p><strong>Returns</strong>: <code>{&quot;ok&quot;: true}</code>.</p><h2 id="overlay-banner" tabindex="-1">overlay_banner <a class="header-anchor" href="#overlay-banner" aria-label="Permalink to &quot;overlay_banner {#overlay-banner}&quot;">​</a></h2><p>Displays a banner colored according to a level, with some text.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Required</th><th>Role</th></tr></thead><tbody><tr><td><code>text</code></td><td>string</td><td>none</td><td><strong>yes</strong></td><td>Banner text</td></tr><tr><td><code>level</code></td><td>string</td><td><code>&quot;L1&quot;</code></td><td>no</td><td>Color: <code>default</code>, <code>L1</code>, <code>L2</code>, <code>L3</code>, <code>L4</code> or <code>gate</code></td></tr></tbody></table><p><strong>Example call</strong></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;text&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Daimon remplit le formulaire&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;level&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;L2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p><strong>Returns</strong>: <code>{&quot;ok&quot;: true}</code>.</p><p><strong>Pitfalls</strong>: an unknown level falls back to <code>default</code>, without error.</p><h2 id="overlay-clear" tabindex="-1">overlay_clear <a class="header-anchor" href="#overlay-clear" aria-label="Permalink to &quot;overlay_clear {#overlay-clear}&quot;">​</a></h2><p>Clears all overlay marks currently on the screen.</p><p><strong>Parameters</strong>: none. <strong>Returns</strong>: <code>{&quot;ok&quot;: true}</code>.</p>',36)])])}const u=t(s,[["render",i]]);export{g as __pageData,u as default};
